	protected Warranty read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Warranty" );

		Warranty entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Warranty with primary key" );
		msg.append( warrantyId );
		
		WarrantyFetchOneSummary fetchOneSummary = new WarrantyFetchOneSummary( warrantyId );

		try {
			entity = WarrantyService.getWarrantyInstance().getWarranty( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Warranty " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Warranty.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Warranty." );

		StringBuilder msg = new StringBuilder( "Failed to update a Warranty : " );        
		Warranty entity = read();
		UpdateWarrantyCommand command = generateUpdateCommand();
		command.setWarrantyId(entity.getWarrantyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Warranty." );

			// for use later on...
			warrantyId = entity.getWarrantyId();

			WarrantyService proxy = WarrantyService.getWarrantyInstance();  

			proxy.updateWarranty( command ).get();

			LOGGER.info( "-- Successfully saved Warranty - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + warrantyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Warranty.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Warranty." );

		Warranty entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Warranty with id " + warrantyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Warranty with id " + warrantyId );

			throw e;
		}

		try{
			WarrantyService.getWarrantyInstance().delete( new DeleteWarrantyCommand( entity.getWarrantyId() ) ).get();
			LOGGER.info( "-- Successfully deleted Warranty with id " + warrantyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Warranty with id " + warrantyId );

			throw e;
		}
	}

	/**
	 * get all Warrantys.
	 */
	protected List<Warranty> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Warrantys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Warranty : " );        
		List<Warranty> collection  = new ArrayList<>();

		try {
			// call the static get method on the WarrantyService
			collection = WarrantyService.getWarrantyInstance().getAllWarranty();
			assertNotNull( collection, "An Empty collection of Warranty was incorrectly returned.");
			
			// Now print out the values
			Warranty entity = null;            
			Iterator<Warranty> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getWarrantyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

